using SpatialWallpaper.Blueprint;

public static class BlueprintBuild {
 const string R="Assets/Blueprint/";
 static T Asset<T>(string path,Func<T> create) where T:UnityEngine.Object {var existing=AssetDatabase.LoadAssetAtPath<T>(R+path);if(existing)return existing;var value=create();AssetDatabase.CreateAsset(value,R+path);return value;}
 static UniversalRenderPipelineAsset Pipeline(int quality){
  var renderer=Asset("Settings/Forward"+quality+".asset",()=>ScriptableObject.CreateInstance<UniversalRendererData>());renderer.name="Blueprint renderer "+quality;renderer.copyDepthMode=CopyDepthMode.AfterOpaques;
  var rd=new SerializedObject(renderer);rd.FindProperty("postProcessData").objectReferenceValue=AssetDatabase.LoadAssetAtPath<UnityEngine.Object>("Packages/com.unity.render-pipelines.universal/Runtime/Data/PostProcessData.asset");rd.ApplyModifiedPropertiesWithoutUndo();
  if(quality>0&&renderer.rendererFeatures.Count==0){var ao=(ScriptableRendererFeature)ScriptableObject.CreateInstance(typeof(UniversalRenderPipelineAsset).Assembly.GetType("UnityEngine.Rendering.Universal.ScreenSpaceAmbientOcclusion",true));ao.name="Blueprint contact shadows";var settings=new SerializedObject(ao);settings.FindProperty("m_Settings.Intensity").floatValue=.6f;settings.FindProperty("m_Settings.Radius").floatValue=.025f;settings.FindProperty("m_Settings.Downsample").boolValue=true;settings.FindProperty("m_Settings.DirectLightingStrength").floatValue=.1f;settings.ApplyModifiedPropertiesWithoutUndo();ao.Create();renderer.rendererFeatures.Add(ao);AssetDatabase.AddObjectToAsset(ao,renderer);}
  var asset=Asset("Settings/Quality"+quality+".asset",()=>UniversalRenderPipelineAsset.Create(renderer));asset.supportsHDR=true;asset.supportsCameraDepthTexture=true;asset.supportsCameraOpaqueTexture=quality>0;asset.msaaSampleCount=quality==0?1:quality==1?2:4;asset.useSRPBatcher=true;asset.maxAdditionalLightsCount=8;asset.shadowDistance=quality==0?2:5;asset.shadowCascadeCount=quality==0?1:2;asset.shadowDepthBias=.05f;asset.shadowNormalBias=.1f;
  var serialized=new SerializedObject(asset);serialized.FindProperty("m_MainLightShadowsSupported").boolValue=true;serialized.FindProperty("m_MainLightShadowmapResolution").intValue=quality==0?1024:quality==1?2048:4096;serialized.FindProperty("m_SoftShadowsSupported").boolValue=quality>0;serialized.FindProperty("m_AdditionalLightsRenderingMode").intValue=(int)LightRenderingMode.PerPixel;serialized.FindProperty("m_AdditionalLightShadowsSupported").boolValue=quality==2;serialized.FindProperty("m_AdditionalLightsShadowmapResolution").intValue=1024;serialized.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(renderer);EditorUtility.SetDirty(asset);return asset;
 }
 static void Materials(){
  var importer=(TextureImporter)AssetImporter.GetAtPath(R+"Resources/Blueprint/Blocks.png");Debug.Log("Blueprint atlas import shape before configuration: "+importer.textureShape);importer.textureType=TextureImporterType.Default;importer.textureShape=TextureImporterShape.Texture2D;importer.filterMode=FilterMode.Point;importer.mipmapEnabled=false;importer.wrapMode=TextureWrapMode.Clamp;importer.sRGBTexture=true;importer.isReadable=false;importer.textureCompression=TextureImporterCompression.CompressedHQ;var platform=importer.GetPlatformTextureSettings("Standalone");platform.name="Standalone";platform.overridden=true;platform.maxTextureSize=1024;platform.format=TextureImporterFormat.BC7;platform.compressionQuality=100;importer.SetPlatformTextureSettings(platform);importer.SaveAndReimport();
  var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(R+"Resources/Blueprint/Blocks.png");if(!texture)throw new InvalidOperationException("Blueprint atlas failed to import");
  foreach(string key in new[]{"grass_block_top","snow","dirt"}){var tileImporter=(TextureImporter)AssetImporter.GetAtPath(R+"Resources/Blueprint/Terrain/"+key+".png");if(tileImporter==null)throw new Exception("Prepare terrain textures first");tileImporter.textureType=TextureImporterType.Default;tileImporter.textureShape=TextureImporterShape.Texture2D;tileImporter.mipmapEnabled=true;tileImporter.filterMode=FilterMode.Point;tileImporter.wrapMode=TextureWrapMode.Repeat;tileImporter.anisoLevel=4;tileImporter.isReadable=false;tileImporter.textureCompression=TextureImporterCompression.CompressedHQ;tileImporter.SaveAndReimport();}
  var shader=AssetDatabase.LoadAssetAtPath<Shader>(R+"Resources/Blueprint/BlueprintLit.shader");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Blueprint pixel lighting shader failed to import");
  foreach(BlockRenderKind kind in Enum.GetValues(typeof(BlockRenderKind))){
   var m=Asset("Resources/Blueprint/Materials/"+kind+".mat",()=>new Material(shader));m.shader=shader;m.SetTexture("_BaseMap",texture);m.SetColor("_BaseColor",Color.white);m.SetColor("_EmissionColor",Color.black);m.SetFloat("_Smoothness",.08f);m.SetFloat("_Cull",2);m.SetFloat("_SrcBlend",1);m.SetFloat("_DstBlend",0);m.SetFloat("_ZWrite",1);m.SetFloat("_Cutoff",.5f);m.DisableKeyword("_ALPHATEST_ON");m.DisableKeyword("_TILING_ON");m.renderQueue=2000;
   if(kind==BlockRenderKind.Cutout||kind==BlockRenderKind.Glow){m.EnableKeyword("_ALPHATEST_ON");m.renderQueue=2450;m.SetOverrideTag("RenderType","TransparentCutout");}
   if(kind==BlockRenderKind.Glass||kind==BlockRenderKind.Water){m.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);m.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);m.SetFloat("_ZWrite",0);m.SetColor("_BaseColor",new Color(1,1,1,kind==BlockRenderKind.Glass?.48f:.78f));m.SetFloat("_Smoothness",.72f);m.renderQueue=3000;m.SetOverrideTag("RenderType","Transparent");}
   if(kind==BlockRenderKind.Glow)m.SetColor("_EmissionColor",new Color(4.5f,2.6f,1.1f));EditorUtility.SetDirty(m);
  }
  var ground=Asset("Resources/Blueprint/Materials/Ground.mat",()=>new Material(shader));EditorUtility.CopySerialized(AssetDatabase.LoadAssetAtPath<Material>(R+"Resources/Blueprint/Materials/Opaque.mat"),ground);ground.EnableKeyword("_TILING_ON");EditorUtility.SetDirty(ground);
  var waterSource=AssetDatabase.LoadAssetAtPath<Material>("Assets/URPWater/Demo/Materials/Water/M_URPWater_Demo_RealTime.mat");if(!waterSource)throw new Exception("Existing URP water resources missing");
  var water=Asset("Resources/Blueprint/Materials/WaterSurface.mat",()=>new Material(waterSource));EditorUtility.CopySerialized(waterSource,water);water.SetColor("_Color",new Color(.08f,.18f,.23f));water.SetColor("_DepthColor",new Color(.025f,.08f,.12f));water.SetFloat("_DepthStart",0);water.SetFloat("_DepthEnd",.06f);water.SetFloat("_ReflectionIntensity",.85f);water.SetFloat("_ReflectionRoughness",.08f);water.SetFloat("_ReflectionDistortion",.04f);water.SetFloat("_Smoothness",.8f);water.SetFloat("_WorldUV",1);water.EnableKeyword("_WORLD_UV");water.SetVector("_NormalMapASpeeds",new Vector4(.025f,.012f,-.01f,.016f));foreach(var keyword in new[]{"_CAUSTICS","_FOAM","_GERSTNER_WAVES"})water.DisableKeyword(keyword);EditorUtility.SetDirty(water);
  var particles=Asset("Resources/Blueprint/Materials/Particles.mat",()=>new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit")));particles.SetColor("_BaseColor",Color.white);particles.SetFloat("_Surface",1);particles.SetFloat("_Blend",0);particles.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);particles.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);particles.SetFloat("_ZWrite",0);particles.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");particles.renderQueue=3000;EditorUtility.SetDirty(particles);
  Asset("Resources/Blueprint/Materials/ReflectionBinding.mat",()=>new Material(Shader.Find("SpatialWallpaper/PoolReflection")));
 }
 [MenuItem("Spatial Wallpaper/Blueprint/Create template")]
 public static void Create(){
  foreach(string folder in new[]{"Settings","Scenes","Resources/Blueprint/Materials"})Directory.CreateDirectory(R+folder);AssetDatabase.Refresh();Materials();
  var editorAssets=Asset("Resources/Blueprint/EditorAssets.asset",()=>ScriptableObject.CreateInstance<BlueprintEditorAssets>());editorAssets.Font=AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/Calibration/Fonts/CalibrationChinese.asset");if(!editorAssets.Font)throw new Exception("Prepare the existing calibration Chinese font before building");EditorUtility.SetDirty(editorAssets);
  var pipelines=new[]{Pipeline(0),Pipeline(1),Pipeline(2)};var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
  var model=new GameObject("SceneModel");model.AddComponent<SceneRenderSettings>().pipeline=pipelines[1];var frame=model.AddComponent<DisplaySceneVolume>();frame.size=new Vector3(.53f,.298125f,6);frame.showGuide=false;
  var runtime=model.AddComponent<BlueprintScene>();var lighting=model.AddComponent<BlueprintLighting>();runtime.Lighting=lighting;lighting.Pipelines=pipelines;
  var sun=new GameObject("Template sun and moon").AddComponent<Light>();sun.transform.SetParent(model.transform,false);sun.type=LightType.Directional;sun.shadows=LightShadows.Soft;sun.shadowBias=.0004f;sun.shadowNormalBias=.003f;sun.intensity=1.2f;sun.transform.rotation=Quaternion.Euler(15,-38,0);lighting.Sun=sun;RenderSettings.sun=sun;
  const string skyRoot="Assets/Blueprint/LocalSky/";
  var skyShader=AssetDatabase.LoadAssetAtPath<Shader>(skyRoot+"CloudyCrownSkybox.shader");if(!skyShader||ShaderUtil.ShaderHasError(skyShader))throw new Exception("Prepare licensed Cloudy Crown Pro with tools/blueprint/prepare_sky.py before building");
  foreach(string name in new[]{"Clouds","Stars","Sun","Moon"}){var importer=(TextureImporter)AssetImporter.GetAtPath(skyRoot+name+".png");importer.textureType=TextureImporterType.Default;importer.textureShape=name=="Clouds"||name=="Stars"?TextureImporterShape.TextureCube:TextureImporterShape.Texture2D;importer.sRGBTexture=false;importer.mipmapEnabled=name!="Stars";importer.filterMode=name=="Stars"?FilterMode.Point:FilterMode.Trilinear;importer.isReadable=false;var platform=importer.GetPlatformTextureSettings("Standalone");platform.overridden=true;platform.maxTextureSize=name=="Stars"?1024:512;platform.format=TextureImporterFormat.BC7;importer.SetPlatformTextureSettings(platform);importer.SaveAndReimport();}
  var sky=Asset("Settings/Sky.mat",()=>new Material(skyShader));sky.shader=skyShader;sky.SetTexture("_CloudsTex",AssetDatabase.LoadAssetAtPath<Cubemap>(skyRoot+"Clouds.png"));sky.SetTexture("_StarsTex",AssetDatabase.LoadAssetAtPath<Cubemap>(skyRoot+"Stars.png"));sky.SetTexture("_SunTex",AssetDatabase.LoadAssetAtPath<Texture2D>(skyRoot+"Sun.png"));sky.SetTexture("_MoonTex",AssetDatabase.LoadAssetAtPath<Texture2D>(skyRoot+"Moon.png"));sky.SetFloat("_CloudsHeight",-.25f);sky.SetFloat("_CloudsOffset",.12f);sky.SetFloat("_CloudsRotationSpeed",.012f);sky.SetFloat("_StarsTwinklingSpeed",.06f);sky.SetFloat("_StarsExtinction",2);sky.SetFloat("_SunSize",.22f);sky.SetFloat("_MoonSize",.25f);sky.SetFloat("_Exposure",1);sky.shaderKeywords=new string[0];EditorUtility.SetDirty(sky);lighting.Sky=sky;RenderSettings.skybox=sky;
  var profile=Asset("Settings/Appearance.asset",()=>ScriptableObject.CreateInstance<VolumeProfile>());
  if(!profile.TryGet<Tonemapping>(out var tone)){tone=profile.Add<Tonemapping>(true);AssetDatabase.AddObjectToAsset(tone,profile);}tone.mode.Override(TonemappingMode.ACES);
  if(!profile.TryGet<Bloom>(out var bloom)){bloom=profile.Add<Bloom>(true);AssetDatabase.AddObjectToAsset(bloom,profile);}bloom.intensity.Override(.32f);bloom.threshold.Override(1.05f);
  if(!profile.TryGet<ColorAdjustments>(out var color)){color=profile.Add<ColorAdjustments>(true);AssetDatabase.AddObjectToAsset(color,profile);}color.postExposure.Override(.25f);
  var effects=new GameObject("Template appearance").AddComponent<Volume>();effects.transform.SetParent(model.transform,false);effects.isGlobal=true;effects.sharedProfile=profile;lighting.Appearance=effects;
  var screen=new GameObject("PhysicalScreenFrame");var camera=new GameObject("DisplayCamera").AddComponent<Camera>();camera.tag="MainCamera";camera.clearFlags=CameraClearFlags.Skybox;camera.allowHDR=true;camera.gameObject.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing=true;
  var projection=camera.gameObject.AddComponent<WindowProjection>();projection.screenFrame=screen.transform;projection.contentDepth=10;projection.SetEye(projection.referenceEye);var cadence=camera.gameObject.AddComponent<AdaptiveRenderCadence>();cadence.projection=projection;cadence.adaptive=false;var driver=camera.gameObject.AddComponent<PreviewEyeDriver>();driver.projection=projection;driver.cadence=cadence;var rig=screen.AddComponent<PhysicalDisplayRig>();rig.projection=projection;rig.sceneModel=model.transform;camera.gameObject.AddComponent<BlueprintCapture>();
  camera.gameObject.AddComponent<BlueprintEditorCheck>();camera.gameObject.AddComponent<BlueprintDropCheck>();camera.gameObject.AddComponent<BlueprintFramingCheck>();PlayerSettings.colorSpace=ColorSpace.Linear;PlayerSettings.runInBackground=true;PlayerSettings.enableFrameTimingStats=true;PlayerSettings.defaultScreenWidth=1280;PlayerSettings.defaultScreenHeight=720;PlayerSettings.fullScreenMode=FullScreenMode.Windowed;
  EditorSceneManager.SaveScene(scene,R+"Scenes/Blueprint.unity");AssetDatabase.SaveAssets();
 }
 public static void Build(){Create();VerifyResources();Directory.CreateDirectory("../Validation/Blueprint");var old=GraphicsSettings.defaultRenderPipeline;GraphicsSettings.defaultRenderPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(R+"Settings/Quality2.asset");
  try{var report=BuildPlayer(new[]{R+"Scenes/Blueprint.unity"},"Builds/Blueprint/Blueprint.exe",BuildTarget.StandaloneWindows64);File.WriteAllText("../Validation/Blueprint/build-result.txt",report.summary.result+" errors="+report.summary.totalErrors);if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Blueprint build failed");}finally{GraphicsSettings.defaultRenderPipeline=old;AssetDatabase.SaveAssets();}
 }
 public static BuildReport BuildPlayer(string[] scenes,string output,BuildTarget target){
  // URP collects variants from build quality settings, not runtime scene references.
  int selected=QualitySettings.GetQualityLevel();var previous=new RenderPipelineAsset[3];
  for(int i=0;i<3;i++){previous[i]=QualitySettings.GetRenderPipelineAssetAt(i);QualitySettings.SetQualityLevel(i,false);QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(R+"Settings/Quality"+i+".asset");}QualitySettings.SetQualityLevel(selected,false);
  try{return BuildPipeline.BuildPlayer(scenes,output,target,BuildOptions.None);}
  finally{for(int i=0;i<3;i++){QualitySettings.SetQualityLevel(i,false);QualitySettings.renderPipeline=previous[i];}QualitySettings.SetQualityLevel(selected,false);}
 }
 public static void VerifyResources(){
  foreach(string name in new[]{"Opaque","Cutout","Glass","Water","Glow","Ground"}){
   var material=AssetDatabase.LoadAssetAtPath<Material>(R+"Resources/Blueprint/Materials/"+name+".mat");var atlas=material?material.GetTexture("_BaseMap"):null;
   if(!atlas||atlas.width!=1024||atlas.height!=1024)throw new InvalidOperationException("Blueprint atlas unbound: "+name);
  }Debug.Log("BLUEPRINT_RESOURCE_CHECK_PASS: all material atlases bound");
 }
}
